abstract class Expr {
    final Token token; Expr(Token t) { this.token = t; }
    abstract String print();
}
final class Binary extends Expr {
    final Expr left, right;                      // named child fields
    Binary(Expr left, Token op, Expr right) { super(op); this.left = left; this.right = right; }
    @Override String print() { return "(" + left.print() + right.print() + ")"; }
}

