    abstract String print();
}
final class Binary extends Expr {
    final Expr left, right;                      // named child fields
    Binary(Expr left, Token op, Expr right) { super(op); this.left = left; this.right = right; }
    @Override String print() { return "(" + left.print() + right.print() + ")"; }
}

sealed interface Expr permits Literal, Binary {}
record Literal(int value) implements Expr {}
record Binary(Expr left, String op, Expr right) implements Expr {}   // named children

static String print(Expr e) {
    return switch (e) {
        case Literal l -> Integer.toString(l.value());
        case Binary b  -> "(" + print(b.left()) + print(b.right()) + ")";
    };                               // exhaustive: no default needed
}
